terraform {
  required_version = ">= 1.7.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"
    }
  }
}

module "networking" {
  source  = "app.terraform.io/acme-corp/networking/aws"
  version = "~> 2.3"

  vpc_cidr             = "10.20.0.0/16"
  environment          = "prod"
  availability_zones   = ["us-east-1a", "us-east-1b", "us-east-1c"]
  enable_nat_gateway   = true
  single_nat_gateway   = false
}

output "vpc_id" {
  value = module.networking.vpc_id
}

// AWS Organizations tag policy (attached at the OU level)
{
  "tags": {
    "team": {
      "tag_key": { "@@assign": "team" },
      "enforced_for": {
        "@@assign": [
          "s3:bucket",
          "redshift:cluster",
          "glue:job",
          "emr:cluster",
          "kinesis:stream"
        ]
      }
    },
    "cost-center": {
      "tag_key": { "@@assign": "cost-center" },
      "tag_value": { "@@assign": ["CC-100", "CC-200", "CC-300"] },
      "enforced_for": {
        "@@assign": [
          "s3:bucket",
          "redshift:cluster",
          "glue:job",
          "emr:cluster",
          "kinesis:stream"
        ]
      }
    }
  }
}

# Monthly Cost Explorer query grouped by the 'team' cost allocation tag
aws ce get-cost-and-usage \
  --time-period Start=2026-09-01,End=2026-10-01 \
  --granularity MONTHLY \
  --metrics "UnblendedCost" \
  --group-by Type=TAG,Key=team
